// battle.c -- the battle module: the field->battle staging (CF/FB65 -> C1/8000 -> FD/A982), the battle loop
// and its interpreters. It works directly on the engine's $7E image, so the staged blocks compare against
// the oracle's WRAM.
// Boot chain (battle_boot.md, battle_menu_synthesis.md 1.7/1.12):
//   FD/B274  party seats   $AEFF+seat <- $2980+slot (active party char-ids)
//   FD/B2A9  enemy ids     $AF02+slot / $AF0D+slot <- slot records $29BF+12k (+5 id, +6 bit 7 empty,
//                          +7 bit 7 hidden -> $AF02 = FF, $AF15 |= 0x80), count $AEC6
//   FD/AE52  PC blocks     $7E2600 + charid*0x50 -> FD/A80B {5E2D,5EAD,5F2D} (seats 0-2)
//   FD/B438  enemy blocks  CC/4700 + id*23 -> $5FAD + slot*0x80 (+0 id, +3 curHP, +5 maxHP, rec+2 -> +0x12,
//                          rec+3..7 -> +0x22, rec+8.. -> +0x37 stats)
// C1/8357 is the controller-2 debug end: every enemy curHP zeroed, $5FCA,Y = 0x80, outcome 0 in $7F01EC.
#include <stdio.h>
#include "romview.h"
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include "battle.h"
static int battleTechGroup(int techId);
static int battleBuildHitSet(CtBattleHost* h, int group, int primary, int* out, int cap);
#include "player.h"      // CtJoypadHeldWord: the battle NMI's C2/84D2 (the pad latch CD/0340 reads $F8)
#include "objslot.h"
void CtHdmaTableBuild(uint8_t* wram128);   // ct_vm.c: `JSL FD/C2C1`, the field's HDMA table builder
#include "lz.h"          // ct_lz_decompress: the CT LZ, used for the enemy sprite sheet (battle_sheet_decomp.md)
#include "tables/battle_fx.h"   // action-feedback bake: CT_FX_RISE_N / CT_FX_LIFETIME (the popup aging bounds)
#include "tables/battle_anim.h" // baked attack/idle trajectories: ctCronoAttackTraj (A2), ctGatoIdleTraj/Bob (ADD.4)
#include "tables/battle_dissolve.h"  // enemy-death dissolve: CT_DISSOLVE_STEPS + the matrix (battle_dissolve.md part 2)
#include "rom_verify.h"
#include "rom_census.h"
#include "tables/battle_trig.h"  // enemy-movement trig tables: ctBattleAtanTab/SinTab/FaceTab (battle_enemy_move_target.md sec. A)

// ---------------------------------------------------------------- ROM tables
static uint8_t* gRom; static long gRomLen;

int CtBattleLoadRom(const char* path) {
  if (gRom) return 1;
  FILE* f = fopen(path, "rb");
  if (!f) return 0;
  fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
  uint8_t* buf = (uint8_t*)malloc((size_t)sz);
  if (!buf || fread(buf, 1, (size_t)sz, f) != (size_t)sz) { free(buf); fclose(f); return 0; }
  fclose(f);
  long rl = sz;                                      // the supported dump only (rom_verify.h)
  const uint8_t* img = CtRomVerify(buf, &rl, path);
  if (!img) { free(buf); return 0; }
  if (img != buf) memmove(buf, img, (size_t)rl);     // a copier header: keep the image at the buffer's start
  gRom = buf; gRomLen = rl;
  CtRomSetPath(path);                                // the process-wide image (rom_verify.h) finds it here too
  CtRomApplyMemPatch(gRom, gRomLen);                 // a measuring tool's instrumentation (CT_ROM_MEMPATCH), after the check
  gRom = CtRomCensusWrapMutable(gRom, gRomLen, "battle");   // CT_ROM_CENSUS: the pages this image's readers touch
  return 1;
}
static int gRomEmpty;
int CtBattleUseEmptyRom(void) {
  if (gRom) return 1;
  gRomEmpty = 1;
  uint8_t* buf = (uint8_t*)calloc(1, CT_ROM_SIZE);
  if (!buf) return 0;
  gRom = CtRomCensusWrapMutable(buf, CT_ROM_SIZE, "battle");      // CT_ROM_CENSUS: a read past the tables shows
  gRomLen = CT_ROM_SIZE;
  CtRomSetImage(gRom, gRomLen);                                  // ... and CtRomImage hands out the same one
  return 1;
}
const uint8_t* CtBattleDumpRom(long* lenOut) {
  static const uint8_t* dump; static long dumpLen; static int tried;
  if (gRom && !gRomEmpty) { if (lenOut) *lenOut = gRomLen; return gRom; }
  if (!tried) {
    tried = 1;
    const char* tries[2] = { getenv("CT_ROM"), "Chrono_Trigger_USA_SNES.sfc" };
    for (int i = 0; i < 2 && !dump; i++) {
      FILE* f = tries[i] && *tries[i] ? fopen(tries[i], "rb") : NULL;
      if (!f) continue;
      fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
      uint8_t* buf = (uint8_t*)malloc((size_t)sz);
      if (buf && fread(buf, 1, (size_t)sz, f) == (size_t)sz) {
        long rl = sz; const uint8_t* img = CtRomVerify(buf, &rl, tries[i]);
        if (img) { if (img != buf) memmove(buf, img, (size_t)rl); dump = buf; dumpLen = rl; buf = NULL;
                   CtRomApplyMemPatch((uint8_t*)dump, dumpLen); }
      }
      free(buf); fclose(f);
    }
  }
  if (lenOut) *lenOut = dump ? dumpLen : 0;
  return dump;
}
const uint8_t* CtBattleRom(long* lenOut) { if (lenOut) *lenOut = gRomLen; return gRom; }

// HiROM file offset = (bank - 0xC0) << 16 | addr16.
#define ROM_ENEMY_STATS 0x0C4700u   /* CC/4700: 23-byte records, +0/+1 HP (FD/B441: id*23) */
#define ROM_ENEMY_NAMES 0x0C6500u   /* CC/6500: 11-byte records, pad 0xEF */
#define ROM_FIELD_RECS  0x24F600u   /* E4/F600: 10-byte field enemy records (op-0x83 loader) */
// ---- Battle-loop ROM data (battle_loop.md) ----
#define ROM_RELOAD_TBL    0x0C2E31u /* CC/2E31: ATB reload speed table (FD/B82F LDA $CC2E31,X) */
#define ROM_PC_ATK_REC    0x0C213Fu /* CC/213F: PC 12-byte attack records; +5 = formula type ($16),
                                       +9 = attack power ($AEEF). Record index resolved per charId. */
#define ROM_PC_ACTION_SEL 0x0C2583u /* CC/2583[charId] -> $B18C, the PC's action id (C1/BFF7-C003). 75..7B. */
#define ROM_PC_ACT_REC    0x0C1BEBu /* CC/1BEB: 11-byte PC action records. $B2C3 = $B18C*11; the attack-id
                                       list starts at +5 (C1/D53A-D5CD); bit 7 terminates it. */
/* FD/B033 -- item id -> its stat record's offset inside bank $CC: five id ranges, five strides (the
   multiply is C1/FDBF -> C1/C90B). C1/CF15 indexes it to derive a PC's battle block. */
#define ROM_EQ_WEAPON     0x0262u   /* id < 0x5A  -> $0262 + id*5                (FD/B037-B04F) */
#define ROM_EQ_ARMOR      0x047Eu   /* id < 0x7B  -> $047E + (id-0x5A)*3         (FD/B056-B071) */
#define ROM_EQ_HELMET     0x04E1u   /* id < 0x94  -> $04E1 + (id-0x7B)*3         (FD/B077-B092) */
#define ROM_EQ_ACCESS     0x052Cu   /* id < 0xBC  -> $052C + (id-0x94)*4         (FD/B098-B0B3) */
/* id < 0xF2 -> $05CC + (id-0xBC)*4 is ROM_ITEM_AMOUNT_TBL, defined below; id >= 0xF2 has no record
   (FD/B0B5 CMP #F2 / BCS ->B0D4 leaves X untouched). */
#define ROM_ENEMY_ATK_REC 0x0C89C6u /* CC/89C6: enemy 12-byte attack records; +9 = attack power */
#define ROM_ENEMY_ACT_REC 0x0C88CAu /* CC/88CA: enemy 11-byte action records (indexed by $B18C); the
                                       attack-id list starts at byte +4, i.e. CC/88CE. C0/1D8D1 */
#define ROM_CLS2_ACT_REC  0x0C6FCAu /* CC/6FCA: the $AEE3==2 class's 11-byte action records, ids at +4
                                       (= CC/6FCE). C0/1D7C4 -- selected by C0/18E09's CMP #02 */
#define ROM_CLS2_ATK_REC  0x0C7AC9u /* CC/7AC9: that class's 12-byte attack records; +9 = power */
#define ROM_RNG_TBL       0x3DBA61u /* FD/BA61: battle RNG byte table (C1/AF56/AF60 LDA $FDBA61,X) */
// ---- Enemy AI interpreter ROM data (battle_interp_verify.md T1). The pointer table, the two
// $FF-delimited blocks and the $FE-delimited cond/action sections are read from the ROM at interpret time. ----
#define ROM_AI_PTR_TABLE  0x0C8B08u /* CC/8B08: per-enemy-id AI script pointer table, id*2 (C1/AFD6) */
// AI action-opcode byte lengths, the cursor-advance rule: the executor reads the opcode at cursor $B1D2
// (C1/8CAC) and dispatches JSR ($B85F,X); the entry's length is FD/BA4A[opcode] (C1/9908, the skip
// handler's advance). Length 0 (op 03) or >= 0x80 (ops 04/05 = 0xFF, variable-length control flow, C1/98C5)
// is not a fixed linear entry: the caller traces and stops. battle_enemy_move_target.md D.3/E.1.
// ---- Battle SFX (battle_sfx_ops.md, battle_sfx_ops_inputs.md). Anim op 0x7C (C1/61EB) posts
// id = CD/6D4C[$A4E7]; C1/4349 writes $A4E7 = $1C48[5 * actingSlot], the slot's equipped weapon id, and
// FD/AF04 fills $1C48 at boot from each battle-PC block's +0x29. Op 0x7D's table CD/6DAC comes from the
// disassembly only; no capture exercises it.
#define ROM_SFX_TBL_7C    0x0D6D4Cu /* CD/6D4C: op-0x7C weapon -> sound id (C1/61EB LDA $CD6D4C,X) */
#define ROM_SFX_TBL_7D    0x0D6DACu /* CD/6DAC: op-0x7D's table (C1/61F5) -- disasm-only, unexercised */
// The op-0x7C post's frame offset is measured (battle_sfx_ops_inputs.md sec. 5), not derived from a ROM
// counter; same family as CT_CRONO_STRIKE / CT_PC_ATK_SPANEND.
#define CT_PC_SFX_AFTER_ARRIVAL  2  /* walk route: post = arrival + 2 (oracle 381->383, 919->921) */
#define CT_PC_SFX_NO_WALK       24  /* no-walk route: post = dispatch + 24 (oracle 601->625) */
#define CT_PC_SFX_CRIT_2ND      41  /* the crit's 0x7D = the 0x7C + 41 (oracle 271->312 and 859->900) */
#define ROM_AI_ACTION_LEN 0x3DBA4Au /* FD/BA4A: action-opcode byte-length table (C1/9908 cursor advance) */
#define ROM_AI_TARGET_TBL 0x01B8BBu /* C1/B8BB: the targeting-byte RESOLVER table, 24 words (value*2) */
#define ROM_CMB_BLOCK_TBL 0x3DA80Bu /* FD/A80B: combatant block bases, one word per seat*2 (C1/AE70
                                       `LDA $FDA80B,X`): 5E2D 5EAD 5F2D 5FAD 602D 60AD, i.e. battleBlock()'s
                                       0x5E2D + idx*0x80 for the three PC seats. */
// ---- Anim-script interpreter ROM data (battle_interp_verify.md T2, part 2 P2.B). The anim selector
// $9877 indexes these pointer tables -> a multi-track bytecode in bank CD; the per-opcode dispatch and
// lengths are read from the ROM at parse time (battleAnimParse). ----
#define ROM_ATK_ANIM_TBL  0x0D5FF0u /* CD/5FF0[$9877*2] -> attack anim-script ptr (C1/4535 LDA $CD5FF0,X) */
#define ROM_TEC_ANIM_TBL  0x0D61F0u /* CD/61F0[$9877*2] -> tech   anim-script ptr (C1/46EF LDA $CD61F0,X) */
#define ROM_ENEMY_ACT_CFG 0x0D5526u /* CD/5526: 7-byte per-action config for an enemy (C1/4693, reached when
                                        $AE91 >= 3), indexed $AE93*7. Same layout as the PC's CD/45A6 and the
                                        item CD/5C26: +0 -> $9877, +1 -> $987A, +2 -> $987B, +6 -> $987C.
                                        Byte +6 decides the action prologue's third staging upload and with
                                        it the pre-roll (battleActStage3). */
/* The PC side has its own two tables, and its scripts live in bank CE, not CD (C1/4623 `LDA $CE0000,X`
   after the tech read names the bank). */
#define ROM_PC_ATK_ANIM_TBL 0x0D5EC6u /* CD/5EC6[$9877*2] -> PC physical script (C1/442C LDA $CD5EC6,X) */
#define ROM_PC_TEC_ANIM_TBL 0x0D5EF0u /* CD/5EF0[$9877*2] -> PC tech     script (C1/4617 LDA $CD5EF0,X) */
#define ROM_ROLE_COACTOR_TBL   0x0CFBC8u   /* CC/FBC8[actor*2]: the two co-actor roles of a party actor (CC/F173) */
#define ROM_PC_ANIM_BANK    0x0E0000L /* bank CE (C1/4623 LDA $CE0000,X) -- the CD tables point into it */
#define ROM_PC_ITM_ANIM_TBL 0x0D63F0u /* CD/63F0[$9877*2] -> PC item script (C1/47C6 LDA $CD63F0,X, then
                                       * C1/47D7 LDA $CE0000,X -- the same bank-CE shape as a tech) */
// ---- PC tech data tables (battle_tech_slice.md). The PC-tech anim path is CD/45A6 (config) + CD/5EF0
// (script base) -> bank CE, distinct from the enemy CD/5FF0/CD/61F0 tables (sec. 0.6): $AE93 = tech id ->
// $9877 = CD/45A6[$AE93*7][0] -> CD/5EF0[$9877*2] -> CE/xxxx. The MP and tech-id-range tables are the ones
// the field tech menu bakes (menu.c ROM_TECH_MP/ROM_TECH_RANGE), read here from the loaded ROM.
#define ROM_FXPAL3_TBL      0x114100u /* D1:4100[p*6]: three colours (anim op 60, C1/5D50) */
#define ROM_FXPAL7_TBL      0x114400u /* D1:4400[p*14]: seven colours (anim op 60 with bit 7, C1/5D7E) */
#define ROM_PC_TEC_ANIM_CFG 0x0D45A6u /* CD/45A6: 7-byte per-tech PC-anim config; +0 = the $9877 selector (sec. 3.2) */
#define ROM_TECH_MP_TBL     0x0C253Bu /* CC/253B[techId] = MP cost (1 byte) (sec. 1) */
#define ROM_TECH_RANGE_TBL  0x02BD40u /* C2/BD40[charId] = cumulative tech-id boundary; char X = ids [tbl[X],tbl[X+1])
                                         = 01 09 11 19 21 29 31 39 3C (sec. 1) */
// The enemy attack anim-selector tables (C1/44AF's two arms), stride-6 records indexed by enemy id.
// Byte +0 is $9877; +1..+5 go to $987A/$987B/$987E/$9881/$9884 (not modelled here).
#define ROM_MOVE_MODE_CLASS  0x0CFBABu /* CC/FBAB: enemy move mode -> handler class, indexed by the raw mode (C1/3756) */
#define ROM_ENEMY_ATK_ANIM_A 0x0D4926u /* CD/4926: the $AE93 == 0 arm (C1/44B4) */
#define ROM_ENEMY_ATK_ANIM_B 0x0D4F26u /* CD/4F26: the $AE93 != 0 arm (C1/44E0) */
#define ROM_ANIM_OP_JT    0x017A6Bu /* C1/7A6B: anim-opcode dispatch jump table, opcode*2 (C1/4CD4 JSR ($7A6B,X)) */
#define ROM_NORMAL_ANIM_TBL 0x0D4007u /* CD/4007: per-charid melee/close anim id (C1/4340, the $9930 != 0
                                        in-range branch): 00 03 05 06 08 0A 0C (battle_3pc_lucca_frog.md sec. 1.3,
                                        battle_polish3.md sec. 3). Its far sibling is CD/4000, its crit CD/400E. */
#define ROM_FAR_ANIM_TBL  0x0D4000u /* CD/4000: per-charid far/ranged anim id (C1/4340, the $9930 == 0
                                        out-of-range branch): 0E 02 04 11 0E 0E 12 (Crono 0x0E when C1/4A71 finds
                                        no walk to the target, e.g. the Dragon Tank's head). */
#define ROM_CRIT_ANIM_TBL 0x0D400Eu /* CD/400E: per-charid crit anim id (C1/438B): 01 0F 10 07 09 0B 0D
                                        (no whole-screen flash, battle_crit.md sec. C.3). */
#define ROM_WEAPON_RANGED_TBL 0x0CF63Cu /* CC/F63C: per-charid weapon-ranged flag (C1/4A40): 01 00 00 01 01 01
                                        01 -- melee (1) always takes C1/4A71's walk test (battleTargetWalkable);
                                        ranged (0) takes it only where the distance test said close. */
#define ROM_REWARD_TBL    0x0C5E00u /* CC/5E00: enemy reward records id*7 (FD/ABD2): +0..1 XP(u16) +2..3
                                        Gold(u16) +4 drop-item +5 charm-item +6 TP(u8) (battle_results_window.md P2) */
// ---- Level-up tables (battle_victory_rewards.md; ROM offset = (bank&0x3F)<<16|addr) ----
#define ROM_XP_THRESH  0x0C2632u /* CC/2632: XP-to-next per level, u16 LE at [level*2]; reload into block+0x2B
                                    (C1/F83D) */
#define ROM_HP_GROW    0x0C258Au /* CC/258A: per-char id*8, up to 4 {levelBreakpoint,HPgain} pairs -- first pair
                                    whose breakpoint >= new level gives the maxHP(+0x5) gain (C1/F871, clamp 999) */
#define ROM_MP_GROW    0x0C25C2u /* CC/25C2: per-char id*8, {levelBreakpoint,MPgain} pairs -> maxMP(+0x9) gain
                                    (C1/F8C0, clamp 99) */
#define ROM_STAT_RATE  0x0C25FAu /* CC/25FA: per-char id*7 growth rates -> stat = base + rate*(level-1)/100
                                    (C1/F633; rate[2]=0 for all -> Speed +0x0D never grows) */
// ---- TP -> tech-learn tables (battle_tech_learn.md; C1/F205 -> F39A -> F45F -> F4DF) ----
#define ROM_TECH_TP    0x0C26FAu /* CC/26FA: per-char TP-per-tech, u16 LE at [charId*16 + learnCount*2] (8/char);
                                    block+0x2D reloads to this after each learn (C1/F3F3). */
#define ROM_TECH_LEARN_RANGE 0x0C276Au /* CC/276A: per-char [baseIdx,maxCount] (C1/F465/F520). baseIdx = the
                                    char's first tech id (== C2/BD40[cid]); maxCount = 8. tech id = baseIdx+learnCount */
#define ROM_TECH_META  0x0C1BEBu /* CC/1BEB: per-tech 11-byte record; byte0 bit 7 = elemental/magic gate (C1/F482):
                                    such a tech needs $7F01E0 bit charId set (magic unlocked) to be learnt */
// ---- Item command tables (battle_item_slice.md; sub = itemId - 0xBC, consumables are id >= 0xBC) ----
#define ROM_ITEM_BATTLE_TBL 0x0C0ABCu /* CC/0ABC: 3-byte item records (sub*3); byte0 = [bit 7 battle-usable][bits 0-6
                                        selector, 0x02 = HP]. Bit 7 clear = field-only, left out of the battle
                                        list (sec. 2.0/2.1). */
#define ROM_ITEM_TGTGRP_TBL 0x0C1BB5u /* CC/1BB5[sub] = target group -> $1581 -> $960D at confirm. Tonic 0x80 (single
                                        PC), Heal 0x00, Revive 0x03, Lapis 0x81 (all-party). (sec. 1) */
#define ROM_ITEM_AMOUNT_TBL 0x0C05CCu /* CC/05CC: 4-byte item effect records (sub*4); +3 = base, +2 = mult -> amount
                                        = base*mult (shared with the field, menu_itemuse.h ctItemFxAmt) (sec. 4). */
#define ROM_ITEM_ANIM_CFG 0x0D5C26u /* CD/5C26: 7-byte per-consumable PC-anim config (sub*7); +0 = the $9877 anim
                                        selector (sec. 5). Distinct from the PC-tech config CD/45A6 and the
                                        enemy tables CD/5FF0/CD/61F0. */

const uint8_t* CtBattleFieldEnemyRecs(void) {
  return gRom ? CtRomPtr(gRom, gRomLen, ROM_FIELD_RECS, 256 * 10) : NULL;   // (the table: CT_ASSET_TABLE)
}

// ---------------------------------------------------------------- Enemy sheet
// The compressed battle-sprite sheet of enemy `gfxid` (the object enemy id $1101): E4:F600[id*10 + 0] = the
// battle-sheet index -> E4:2000[idx*3] = a 24-bit pointer to the LZ-compressed sheet (battle_sheet_decomp.md).
// Returns the HiROM file offset, or -1 if the ROM is absent or the entry is out of range. E4:2000 is the one
// graphics-source table shared with the field sprites.
#define ROM_GFX_SRC_TBL 0x242000u   /* E4/2000: 24-bit graphics-source pointers (PC/field/battle sheets) */
long CtBattleEnemySheetSrc(int gfxid) {
  if (!gRom || gfxid < 0 || gfxid > 0xFF) return -1;
  if (gRomLen < (long)(ROM_FIELD_RECS + 256 * 10)) return -1;
  int bidx = CtRomByte(gRom, 0x400000L, (long)(ROM_FIELD_RECS + (unsigned)gfxid * 10 + 0));   // +0 = battle-sheet index into E4:2000
  long ent = (long)ROM_GFX_SRC_TBL + (long)bidx * 3;
  if (ent + 3 > gRomLen) return -1;
  int bank = CtRomByte(gRom, 0x400000L, (long)(ent + 2)), a16 = CtRomByte(gRom, 0x400000L, (long)(ent)) | (CtRomByte(gRom, 0x400000L, (long)(ent + 1)) << 8);
  if (bank < 0xC0) return -1;                                    // must be a HiROM code/data bank
  return ((long)(bank - 0xC0) << 16) | a16;
}

// Decompresses enemy `gfxid`'s sheet into `out`, up to `maxBytes` of the 4bpp stream (8x8 tiles at
// out + tile*0x20). Returns bytes written (0 on failure). Goes through a private scratch because
// ct_lz_decompress is unbounded.
int CtBattleDecompressEnemySheet(int gfxid, uint8_t* out, int maxBytes) {
  static uint8_t scratch[1 << 17];   // 128 KB (any CT sheet decompresses to <= ~0x3000)
  long src = CtBattleEnemySheetSrc(gfxid);
  if (src < 0 || !out || maxBytes <= 0) return 0;
  size_t n = ct_lz_decompress(gRom, scratch, (size_t)src);
  if (n == 0) return 0;
  int copy = (n < (size_t)maxBytes) ? (int)n : maxBytes;
  memcpy(out, scratch, (size_t)copy);
  return copy;
}

// ---------------------------------------------------------------- Enemy pose staging
// The battle-entry staging CC/EAD2-EB60 as a function of the enemy id (battle_pose_staging.md sec. 2):
//   record +3 = initial animId $8E -> E4:2600[$8E*2] = ptrA ($1CA2), E4:2800[$8E*2] = ptrB ($1CC3), bank E4
//   record +1 = packet index       -> E4:2300[pkt*3]  = the 24-bit E3 assembly base ($1C78)
//   record +0 = battle-sheet index -> E4:2000[idx*3]  = the 24-bit compressed-sheet source
//   stride $9671 = (E4:2600[$8E+1] - E4:2600[$8E]) >> 2   (one animId's ptrA block / 4)
// Returns SNES 24-bit addresses, as the ROM stores them.
#define ROM_GFX_ASM_TBL  0x242300u   /* E4/2300: 24-bit E3-assembly base pointers (parallel to E4/2000, packet idx) */
#define ROM_POSE_A_TBL   0x242600u   /* E4/2600: 16-bit ptrA (pose-script A = assembly-frame windows), animId idx */
#define ROM_POSE_B_TBL   0x242800u   /* E4/2800: 16-bit ptrB (pose-script B = per-frame durations), animId idx */
#define ROM_POSE_CLASS_TBL 0x0CFB91u /* CC/FB91: mode -> pose class (0/1/2); the tick maps class -> $86 base */

static long romRd24(uint32_t off) {   // 24-bit LE ROM pointer -> value; requires gRom valid + in range
  return (long)CtRomByte(gRom, 0x400000L, (long)(off)) | ((long)CtRomByte(gRom, 0x400000L, (long)(off + 1)) << 8) | ((long)CtRomByte(gRom, 0x400000L, (long)(off + 2)) << 16);
}
static int romRd16(uint32_t off) { return CtRomByte(gRom, 0x400000L, (long)(off)) | (CtRomByte(gRom, 0x400000L, (long)(off + 1)) << 8); }

int CtBattleEnemyPoseStage(int id, CtEnemyPoseStage* out) {
  if (!out || !gRom || id < 0 || id > 0xFF) return 0;
  if (gRomLen < (long)(ROM_FIELD_RECS + 256 * 10)) return 0;
  const uint8_t* r = CtRomPtr(gRom, gRomLen, ROM_FIELD_RECS + (long)id * 10, 10);
  out->animId = r[3]; out->packet = r[1]; out->palIdx = r[2]; out->sizeByte = r[4];
  int an = r[3], pkt = r[1], sh = r[0];
  out->ptrA    = 0xE40000L | romRd16(ROM_POSE_A_TBL + (unsigned)an * 2);   // bank E4 (staging CC/EB23)
  out->ptrB    = 0xE40000L | romRd16(ROM_POSE_B_TBL + (unsigned)an * 2);   // bank E4 (staging CC/EB2A)
  out->e3base  = romRd24(ROM_GFX_ASM_TBL + (unsigned)pkt * 3);             // $1C78/$1C81 (staging CC/EAF7)
  out->sheetSrc= romRd24(ROM_GFX_SRC_TBL + (unsigned)sh * 3);              // the compressed sheet (E4/2000[+0])
  out->stride  = (romRd16(ROM_POSE_A_TBL + (unsigned)(an + 1) * 2)
                  - romRd16(ROM_POSE_A_TBL + (unsigned)an * 2)) >> 2;      // $9671 (staging CC/EB40)
  return 1;
}

// The idle rest assembly index (cursor 0 of the idle window) from the staged mode ($974A) and facing ($96E9),
// as the pose tick computes it (C1/33AE-33D5): mode -> class (CC/FB91[mode]) -> class base $86 (class 0 #0C,
// class 1 #04, class >= 2 #18) -> window $82 = $86 + facing*stride -> ptrA[$82]. Cursor 0 needs no
// $97D9 -> $967B remap (battle_pose_staging.md sec. 5). Returns the rest E3 index, or -1 on failure.
int CtBattleEnemyIdleRest(int id, int mode, int facing) {
  CtEnemyPoseStage st;
  if (!CtBattleEnemyPoseStage(id, &st)) return -1;
  if (mode < 0 || mode > 0xFF || facing < 0 || facing > 3) return -1;
  int cls  = CtRomByte(gRom, 0x400000L, (long)(ROM_POSE_CLASS_TBL + (unsigned)mode));          // CC/FB91[mode] -> class 0/1/2
  int base = (cls == 0) ? 0x0C : (cls == 1) ? 0x04 : 0x18;       // tick class->$86 immediate
  int off  = base + facing * st.stride;                          // $82 = $86 + facing*stride
  uint32_t ptrAflat = 0x240000u | ((uint32_t)st.ptrA & 0xFFFF);  // bank E4 -> flat file offset
  if ((long)(ptrAflat + off) >= gRomLen) return -1;
  return CtRomByte(gRom, 0x400000L, (long)(ptrAflat + off));                                   // cursor 0 = the rest index
}

// Idle-pose gather coverage: decodes the idle rest E3 record's cell-words (E3 base + rest*stride) and counts
// the non-blank ones whose tile the decompressed sheet holds. `ncell` = the enemy's OBJ-cell count (record
// stride ncell*10, ncell*4 cell-words). Returns the covered count, *nonblank = the non-blank count, -1 on
// failure. A check that the idle pose draws with no missing tile (battle_pose_staging.md sec. 5).
int CtBattleEnemyIdleGather(int id, int mode, int facing, int ncell, int* nonblank) {
  if (nonblank) *nonblank = 0;
  CtEnemyPoseStage st;
  int rest = CtBattleEnemyIdleRest(id, mode, facing);
  if (rest < 0 || !CtBattleEnemyPoseStage(id, &st) || ncell < 1 || ncell > 16) return -1;
  static uint8_t sheet[1 << 17];
  int n = CtBattleDecompressEnemySheet(id, sheet, (int)sizeof sheet);
  if (n <= 0) return -1;
  int ntiles = n / 32, ncw = ncell * 4;
  uint32_t e3flat = (uint32_t)((((st.e3base >> 16) - 0xC0) << 16) | (st.e3base & 0xFFFF));
  uint32_t rec = e3flat + (uint32_t)rest * (uint32_t)(ncell * 10);   // record = base + idx*stride
  if ((long)(rec + (uint32_t)ncw * 2) > gRomLen) return -1;
  int nb = 0, cov = 0;
  for (int i = 0; i < ncw; i++) {
    int src = (CtRomByte(gRom, 0x400000L, (long)(rec + i * 2)) | (CtRomByte(gRom, 0x400000L, (long)(rec + i * 2 + 1)) << 8)) & 0x07FF;   // cell-word: srcTile bits0-10
    if (!src) continue;                                                     // word 0 = blank/skip
    nb++;
    if (src < ntiles) cov++;                                                // the sheet has this tile
  }
  if (nonblank) *nonblank = nb;
  return cov;
}

// ---------------------------------------------------------------- Facing engine (battle_facing_engine.md)
// PC pose staging (CC/E97E): the same E4 tables keyed by charId 0..6.
int CtBattlePcPoseStage(int charId, long* e3base, long* sheetBase, long* ptrA, long* ptrB, int* stride) {
  if (!gRom || charId < 0 || charId > 6) return 0;
  long sh = romRd24(ROM_GFX_SRC_TBL + (unsigned)charId * 3);      // CE990: $1C57 <- E4:2000[cid*3] (raw 4bpp)
  long e3 = romRd24(ROM_GFX_ASM_TBL + (unsigned)charId * 3);      // CE9A5: $1C78 <- E4:2300[cid*3]
  int pa = romRd16(ROM_POSE_A_TBL + (unsigned)charId * 2);        // CE9BC: $1C99 <- E4:2600[cid*2] (bank E4)
  int pb = romRd16(ROM_POSE_B_TBL + (unsigned)charId * 2);        // CE9D3: $1CBA <- E4:2800[cid*2]
  int st = (romRd16(ROM_POSE_A_TBL + (unsigned)(charId + 1) * 2) - pa) >> 2;   // CEA0A: $966E stride
  if (e3base) *e3base = e3;
  if (sheetBase) *sheetBase = sh;
  if (ptrA) *ptrA = pa;
  if (ptrB) *ptrB = pb;
  if (stride) *stride = st;
  return 1;
}
// ---- Per-combatant status scan (C1/2F97, battle_status_render.md) ----
// One table-driven machine yields the pose class and the icon state for every status:
//   block = $5E2D + cmb*0x80        status byte 1 at block+0x1E (sleep = mask 0x04)
//   base  = $5E4A + cmb*0x80        the CC/F77F record offsets are relative to this
//   records at CC/F77F: {+0 offset (bit 7 = end), +1 mask, +2 iconState, +3 pose class}
//   first match wins; cls 0xFF -> 3; iconState bit 7 -> no icon.
#define ROM_STATUS_SCAN_TBL 0x0CF77Fu
// When no record matches (C1/302C-3058): block +$02 bit 0 (the low-HP bit C1/B093 keeps, curHP <= maxHP / 8)
// with $A09B,Y == 0 gives $A441,Y := 80 (no icon) and pose class $12 (the kneel window, +$48), and resets a
// PC's pose cursor when `LDA #12 / CMP $A44C,Y` differs (C1/3041-3050). *lowHp reports it.
void CtBattleStatusScanEx(const uint8_t* mem, int cmb, int* poseCls, int* iconState, int* lowHp) {
  int cls = 3, icon = -1, low = 0, hit = 0;                // C1/2F97 defaults ($A09B/$A0A7 == 0 observed)
  if (mem && gRom && cmb >= 0 && cmb < 11 && (long)(ROM_STATUS_SCAN_TBL + 4) <= gRomLen) {
    uint32_t base = 0x5E4Au + (uint32_t)cmb * 0x80u;
    for (uint32_t r = ROM_STATUS_SCAN_TBL; (long)(r + 4) <= gRomLen; r += 4) {
      uint8_t off = CtRomByte(gRom, 0x400000L, (long)(r));
      if (off & 0x80) break;                               // bit 7 = end of the record list
      if (mem[base + off] & CtRomByte(gRom, 0x400000L, (long)(r + 1))) {                  // +1 = the bit mask
        uint8_t st = CtRomByte(gRom, 0x400000L, (long)(r + 2)), cl = CtRomByte(gRom, 0x400000L, (long)(r + 3));
        cls  = (cl == 0xFF) ? 3 : cl;                       // +3 = the pose class
        icon = (st & 0x80) ? -1 : st;                       // +2 = the icon state (bit 7 = none, e.g. dead)
        hit = 1;
        break;                                              // first match wins
      }
    }
    if (!hit && (mem[0x5E2F + (uint32_t)cmb * 0x80u] & 0x01) && !mem[0xA09B + cmb]) {   // C1/302C-303A
      cls = 0x12; icon = -1; low = 1;                       // C1/303C-3054 ($A441 := 80: no icon)
    }
  }
  if (poseCls)   *poseCls   = cls;
  if (iconState) *iconState = icon;
  if (lowHp)     *lowHp     = low;
}
void CtBattleStatusScan(const uint8_t* mem, int cmb, int* poseCls, int* iconState) {
  CtBattleStatusScanEx(mem, cmb, poseCls, iconState, NULL);
}

// ---- Status icon (C1/308C dispatch -> ($3216,X) handlers -> CC/F6D4 records) ----
// battle_status_render.md sec. 3.1/3.2/6. The dispatch runs for all 11 combatants every frame and, when a
// combatant's icon state changes, calls the state's handler through C1/3216. Each handler arms a group byte
// offset into CC/F6D4, a dwell period from CC/F5FD+k, and the visibility flag. A group is 4 consecutive
// {int8 dx, int8 dy, uint8 tile, uint8 attr} records that the cursor cycles. Sleep's icon keeps dx/dy
// constant and swaps two tiles (0x1A6 <-> 0x1C6); other statuses' groups (0x50-0x70) do move.
#define ROM_STATUS_ICON_TBL    0x0CF6D4u   // 32 x 4-byte OAM records
#define ROM_STATUS_ICON_PERIOD 0x0CF5FDu   // the per-handler dwell periods
#define ROM_STATUS_ICON_SHEET  0x113900u   // the icon tile sheet; index = vramTile - 0x1A0

// CF/EE60-EE8F: the record the OAM builder draws for an armed icon, CC/F6D4[$A4D0,X + $A4DB,X * 4] (the
// handler's group offset plus the builder's 4-step cursor). Returns 0 when there is nothing to draw: the icon
// is not armed ($A48E), or $A4DB still holds the arm's $FF (the build pass runs before the main loop's arm in
// a frame, so an icon armed this frame is first drawn the next).
int CtBattleStatusIconLive(const uint8_t* mem, int cmb, int* dx, int* dy, int* tile, int* pal) {
  if (!gRom || !mem || cmb < 0 || cmb > 10) return 0;
  if (!mem[0xA48E + cmb]) return 0;
  int cur = mem[0xA4DB + cmb];
  if (cur > 3) return 0;
  uint32_t r = ROM_STATUS_ICON_TBL + (uint32_t)mem[0xA4D0 + cmb] + (uint32_t)cur * 4u;
  if ((long)(r + 4) > gRomLen) return 0;
  if (dx)   *dx   = (int)(int8_t)CtRomByte(gRom, 0x400000L, (long)(r));
  if (dy)   *dy   = (int)(int8_t)CtRomByte(gRom, 0x400000L, (long)(r + 1));
  if (tile) *tile = 0x100 | CtRomByte(gRom, 0x400000L, (long)(r + 2));
  if (pal)  *pal  = ((CtRomByte(gRom, 0x400000L, (long)(r + 3)) | mem[0xA5E3]) >> 1) & 7;      // FEE88 ORA $A5E3 (0x30: priority bits only)
  return 1;
}
// The icon's 4bpp tile data, mirroring CtBattlePcSheetTile's shape. vramTile is the full 0x1xx name.
// The ground shadow (CF/EA8A, drawn while $A5D8,X is set and $9FF7,X is clear): one 16x16 OAM entry at
// ($1D0C-8, $1D23-4), name $02, attribute $A5E3 | $9F46 (priority 3, OBJ palette 1). VRAM names $02/$03 match
// D1/5E82 (32 bytes each), found by byte search on a capture; the upload routine is not derived. Names
// $12/$13 are blank. OBJ palette 1's colours 13-15 come from the boot's copy CC/E6D5 (FF:9E0A -> $213A).
#define ROM_BATTLE_SHADOW_TILE 0x115E82u   /* D1/5E82: names $02,$03 */
#define ROM_BATTLE_OBJPAL1_TAIL 0x3F9E0Au  /* FF:9E0A: OBJ palette 1 colours 13..15 (CC/E6D5 -> $213A) */
const uint8_t* CtBattleShadowTile(int q) {             // q = 0..3 = names $02, $03, $12, $13 (the last two blank)
  static const uint8_t blank[32] = { 0 };
  if (!gRom || q < 0 || q > 3) return NULL;
  if (q >= 2) return blank;
  uint32_t a = ROM_BATTLE_SHADOW_TILE + (uint32_t)q * 32u;
  return CtRomPtr(gRom, gRomLen, a, 32);
}
// The boot's UI OBJ tiles: DMA channel 7 uploads at CC/E047-E0A1 and CC/E0EB-E147, 0x40 bytes (two 8x8 tiles)
// each from bank D1: D1/5EC2 -> $0060 (names 06 07, the selection bracket's corner), D1/5E82 -> $0020 (names
// 02 03, the ground shadow), D1/5F02 -> $0160 (names 16 17) and $0120 (names 12 13), the blank lower halves.
// CC/E22E: FF:9CF0 -> $0000 (names 00 01) and FF:9D30 -> $0100 (names 10 11), the target hand.
const uint8_t* CtBattleUiObjTile(int name) {
  long a;
  switch (name) {
    case 0x00: case 0x01: a = 0x3F9CF0L + (name - 0x00) * 32; break;
    case 0x10: case 0x11: a = 0x3F9D30L + (name - 0x10) * 32; break;
    case 0x02: case 0x03: a = 0x115E82L + (name - 0x02) * 32; break;
    case 0x06: case 0x07: a = 0x115EC2L + (name - 0x06) * 32; break;
    case 0x12: case 0x13: a = 0x115F02L + (name - 0x12) * 32; break;
    case 0x16: case 0x17: a = 0x115F02L + (name - 0x16) * 32; break;
    default: return NULL;
  }
  return gRom ? CtRomPtr(gRom, gRomLen, a, 32) : NULL;
}
int CtBattleObjPal1Tail(uint16_t out[16]) {           // colours 13..15 filled; the rest 0 (not derived here)
  if (!gRom || (long)(ROM_BATTLE_OBJPAL1_TAIL + 6) > gRomLen) return 0;
  for (int k = 0; k < 16; k++) out[k] = 0;
  for (int k = 0; k < 3; k++)
    out[13 + k] = (uint16_t)(CtRomByte(gRom, 0x400000L, (long)(ROM_BATTLE_OBJPAL1_TAIL + k * 2)) | (CtRomByte(gRom, 0x400000L, (long)(ROM_BATTLE_OBJPAL1_TAIL + k * 2 + 1)) << 8));
  return 1;
}
const uint8_t* CtBattleStatusIconTile(int vramTile) {
  if (!gRom || vramTile < 0x1A0) return NULL;
  uint32_t a = ROM_STATUS_ICON_SHEET + (uint32_t)(vramTile - 0x1A0) * 32u;
  return CtRomPtr(gRom, gRomLen, a, 32);
}

int CtBattlePcIdleWin(int charId, int facing, uint8_t poses[4], uint8_t dwells[4]) {
  long pa; int st;
  if (!CtBattlePcPoseStage(charId, 0, 0, &pa, 0, &st)) return 0;
  if (facing < 0 || facing > 3) return 0;
  uint32_t a = 0x240000u + (uint32_t)pa + (uint32_t)facing * (uint32_t)st + 3u * 4u;   // status class 3
  if ((long)(a + 4) > gRomLen) return 0;
  for (int i = 0; i < 4; i++) { if (poses) poses[i] = CtRomByte(gRom, 0x400000L, (long)(a + i)); if (dwells) dwells[i] = 0; }
  // Dwells are not decoded here (always 0): battlePcWalk reads them through CtBattlePcWinDwell.
  return 1;
}
int CtBattlePcWinPose(int charId, int winOff, int entry, int facing) {
  long pa; int st;
  if (!CtBattlePcPoseStage(charId, 0, 0, &pa, 0, &st)) return -1;
  if (facing < 0 || facing > 3 || winOff < 0 || entry < 0) return -1;
  uint32_t a = 0x240000u + (uint32_t)pa + (uint32_t)facing * (uint32_t)st + (uint32_t)(winOff + entry);
  if ((long)(a + 1) > gRomLen) return -1;
  int v = CtRomByte(gRom, 0x400000L, (long)(a));
  return (v == 0xFF) ? -1 : v;
}
// The per-entry dwell of a PC pose window, from ptrB (battle_pc_attack_sequencing.md sec. 2.1):
// E4:ptrB[charId] + winOff + entry, in frames. Unlike the pose byte it has no facing term: the pose index
// adds $82 = facing*stride at C1/42F6, the dwell reload at C1/42C9 does not, and C1/42EE stores the raw byte.
// 0 = the window terminator; -1 on failure.
int CtBattlePcWinDwell(int charId, int winOff, int entry) {
  long pb;
  if (!CtBattlePcPoseStage(charId, 0, 0, 0, &pb, 0)) return -1;
  if (winOff < 0 || entry < 0) return -1;
  uint32_t a = 0x240000u + (uint32_t)pb + (uint32_t)(winOff + entry);
  if ((long)(a + 1) > gRomLen) return -1;
  return CtRomByte(gRom, 0x400000L, (long)(a));
}
int CtBattlePcE3Rec(int charId, int idx, uint16_t cw[16], int8_t pos[8]) {
  long e3;
  if (!CtBattlePcPoseStage(charId, &e3, 0, 0, 0, 0)) return 0;
  uint32_t fl = (uint32_t)((((e3 >> 16) - 0xC0) << 16) | (e3 & 0xFFFF)) + (uint32_t)idx * 0x28;
  if ((long)(fl + 0x28) > gRomLen) return 0;
  for (int i = 0; i < 16; i++) cw[i] = (uint16_t)(CtRomByte(gRom, 0x400000L, (long)(fl + i * 2)) | (CtRomByte(gRom, 0x400000L, (long)(fl + i * 2 + 1)) << 8));
  for (int i = 0; i < 8; i++) pos[i] = (int8_t)CtRomByte(gRom, 0x400000L, (long)(fl + 0x20 + i));
  return 1;
}
const uint8_t* CtBattlePcSheetTile(int charId, int src) {
  long sh;
  if (!CtBattlePcPoseStage(charId, 0, &sh, 0, 0, 0) || src <= 0) return NULL;
  uint32_t fl = (uint32_t)((((sh >> 16) - 0xC0) << 16) | (sh & 0xFFFF)) + (uint32_t)src * 0x20;
  if ((long)(fl + 0x20) > gRomLen) return NULL;
  return CtRomPtr(gRom, gRomLen, fl, 0x20);
}
int CtBattleEnemyE3Rec(int id, int idx, int type, uint16_t cw[96], int8_t pos[48]) {
  CtEnemyPoseStage st;
  if (!CtBattleEnemyPoseStage(id, &st)) return 0;
  // Staged rec +7 & 7 -> $967C (CC/EA70-EA75); C1/1C69 `LDA $967C,X / ASL / LDA $CCF40A,X` reads the record
  // stride: CC:F40A = 0028 0050 0078 00F0 for types 0..3 = 4/8/12/24 cells * 10 bytes.
  if (type < 0 || type > 3 || (long)(0x0CF40A + type * 2 + 1) >= gRomLen) return 0;
  int rs = CtRomByte(gRom, 0x400000L, (long)(0x0CF40A + type * 2)) | (CtRomByte(gRom, 0x400000L, (long)(0x0CF40A + type * 2 + 1)) << 8);
  int ncell = rs / 10;                                            // record = [ncell*4 words][ncell dx,dy]
  if (ncell > 24) return 0;                                       // (the caller's buffers hold 24 cells)
  uint32_t fl = (uint32_t)((((st.e3base >> 16) - 0xC0) << 16) | (st.e3base & 0xFFFF)) + (uint32_t)idx * (uint32_t)rs;
  if ((long)(fl + (uint32_t)rs) > gRomLen) return 0;
  for (int i = 0; i < ncell * 4; i++) cw[i] = (uint16_t)(CtRomByte(gRom, 0x400000L, (long)(fl + i * 2)) | (CtRomByte(gRom, 0x400000L, (long)(fl + i * 2 + 1)) << 8));
  for (int i = 0; i < ncell * 2; i++) pos[i] = (int8_t)CtRomByte(gRom, 0x400000L, (long)(fl + (uint32_t)(ncell * 8) + i));
  return ncell;
}
// A combatant's cells, for every record type. Three ROM pieces decide which tile words a cell shows:
//  * the gather, C1/1C4A-1F3C (on a pose change): the record's words are copied row by row into the $7E OBJ
//    VRAM mirror, row r at CC:F941[cmb*2] + CC:F3B6[layout*14 + r*2], W words per row (+12), `rows` rows (+13).
//    The layout is the type, except type 2 outside combatant 3 takes layout 5 (C1/1CA9-1CB8). A word whose low
//    11 bits are 0 clears its tile; bit 14 flips it (C1/1DD3, C0:FD00).
//  * the upload, CF/E414 (NMI, one pair per frame): mirror CC:F957[k] -> VRAM word CC:F967[k], so mirror byte m
//    is VRAM tile (m - $63AD) / 32.
//  * the names, CF/EB94: combatant cmb's cells copy the OAM template from CC:F84D[(0x0C + cmb)*2] = $11B0 +
//    cmb*16 on, which CC/ED87 fills from CC:FAF3 (44 name/attribute pairs). A big enemy's cells run on into the
//    next combatants' entries. Cell c's 16x16 sprite is VRAM tiles N, N+1, N+16, N+17.
// A cell whose tile this combatant never wrote shows whatever VRAM holds on the cartridge; this returns word 0
// (blank) for it. A cell past the template's 44 entries is dropped.
#define ROM_POSE_ROWS_TBL      0x0CF3B6u   /* CC:F3B6: 14-byte row layouts (six offsets, words per row, rows)    */
#define ROM_POSE_DEST_TBL      0x0CF941u   /* CC:F941: a combatant's first byte in the $7E OBJ mirror (C1/1CEB)  */
#define ROM_OBJ_UPLOAD_SRC     0x0CF957u   /* CC:F957: the NMI's upload sources (CF/E414)                        */
#define ROM_OBJ_UPLOAD_VRAM    0x0CF967u   /* CC:F967: their VRAM word addresses (CF/E434)                       */
#define ROM_OAM_TEMPLATE_PTR   0x0CF84Du   /* CC:F84D: an object's template entry (CF/E8E3)                      */
#define ROM_OAM_TEMPLATE       0x0CFAF3u   /* CC:FAF3: the name/attribute pairs CC/ED87 copies to $11B0          */
#define WRAM_OAM_TEMPLATE      0x11B0      /* CC/ED8B `STA $11B0,Y`                                              */
#define OAM_TEMPLATE_ENTRIES   44          /* CC/EDA5 `CPY #00B0`: 0xB0 / 4                                      */
int CtBattleEnemyCells(int cmb, int id, int pose, int type, CtEnemyCell* out, int max) {
  if (!gRom || cmb < 0 || cmb >= 11 || type < 0 || type > 3 || !out) return 0;
  if ((long)(ROM_OAM_TEMPLATE + 2 * OAM_TEMPLATE_ENTRIES) > gRomLen) return 0;
  uint16_t cw[96]; int8_t pos[48];
  int n = CtBattleEnemyE3Rec(id, pose, type, cw, pos);
  if (n <= 0) return 0;
  #define RD16(a) ((int)(CtRomByte(gRom, 0x400000L, (long)((a))) | (CtRomByte(gRom, 0x400000L, (long)((a) + 1)) << 8)))
  int lay = (type == 2 && cmb != 3) ? 5 : type;                      // C1/1CA6-1CB8
  const uint8_t* b = CtRomPtr(gRom, gRomLen, ROM_POSE_ROWS_TBL + (long)lay * 14, 14);
  int W = b[12], rows = b[13];                                       // C1/1CC3-1CCF
  int dst = RD16(ROM_POSE_DEST_TBL + (uint32_t)cmb * 2u);            // C1/1CEB
  int mirror0 = RD16(ROM_OBJ_UPLOAD_SRC) - 2 * RD16(ROM_OBJ_UPLOAD_VRAM);
  int16_t vt[256];
  for (int i = 0; i < 256; i++) vt[i] = -1;
  for (int r = 0, w = 0; r < rows && r < 6; r++) {                   // C1/1CE7-1F39
    int off = b[2 * r] | (b[2 * r + 1] << 8);
    for (int i = 0; i < W; i++, w++) {
      int a = dst + off + i * 0x20 - mirror0;
      if (a < 0 || (a & 0x1F) || w >= n * 4) continue;
      if ((a >> 5) < 256) vt[a >> 5] = (int16_t)w;
    }
  }
  int k0 = (RD16(ROM_OAM_TEMPLATE_PTR + (uint32_t)(0x0C + cmb) * 2u) - WRAM_OAM_TEMPLATE) / 4;
  #undef RD16
  int m = 0;
  for (int c = 0; c < n && m < max; c++) {
    int k = k0 + c;
    if (k < 0 || k >= OAM_TEMPLATE_ENTRIES) continue;
    int nm = CtRomByte(gRom, 0x400000L, (long)(ROM_OAM_TEMPLATE + (uint32_t)k * 2u));
    const int sub[4] = { nm, nm + 1, nm + 16, nm + 17 };
    CtEnemyCell* e = &out[m++];
    e->name = (uint8_t)nm; e->dx = pos[2 * c]; e->dy = pos[2 * c + 1];
    for (int q = 0; q < 4; q++) e->w[q] = (sub[q] < 256 && vt[sub[q]] >= 0) ? cw[vt[sub[q]]] : 0;
  }
  return m;
}
#define ROM_ENEMY_PAL_TBL 0x240000u   /* E4/0000 + record[+2]*24 = OBJ colors 1..12 */
int CtBattleEnemyPalRom(int id, uint16_t out[16]) {
  if (!gRom || id < 0 || id > 0xFF) return 0;
  int pi = CtRomByte(gRom, 0x400000L, (long)(ROM_FIELD_RECS + (unsigned)id * 10 + 2));
  uint32_t fl = ROM_ENEMY_PAL_TBL + (uint32_t)pi * 24;
  if ((long)(fl + 24) > gRomLen) return 0;
  memset(out, 0, 16 * sizeof(uint16_t));                          // idx 0 transparent; 13-15 unused
  for (int c = 0; c < 12; c++) out[1 + c] = (uint16_t)(CtRomByte(gRom, 0x400000L, (long)(fl + c * 2)) | (CtRomByte(gRom, 0x400000L, (long)(fl + c * 2 + 1)) << 8));
  return 1;
}
#define ROM_DWELL_REMAP_TBL 0x0CFBCEu /* CC/FBCE: raw ptrB byte -> dwell ticks (floor(raw/5) staircase);
                                         the tick C1/33F4-33FD: $9799[k] = CC/FBCE[[ptrB]+$86+k] */
int CtBattleEnemyIdleWin(int id, int mode, int facing, uint8_t poses[8], uint8_t dwells[8]) {
  CtEnemyPoseStage st;
  if (!CtBattleEnemyPoseStage(id, &st)) return 0;
  if (mode < 0 || mode > 0xFF || facing < 0 || facing > 3) return 0;
  int cls  = CtRomByte(gRom, 0x400000L, (long)(ROM_POSE_CLASS_TBL + (unsigned)mode));           // CC/FB91[mode]
  int base = (cls == 0) ? 0x0C : (cls == 1) ? 0x04 : 0x18;        // = anims 3 / 1 / 6, i.e. anim*4
  int off  = base + facing * st.stride;
  uint32_t a = 0x240000u | ((uint32_t)st.ptrA & 0xFFFF);
  uint32_t b = 0x240000u | ((uint32_t)st.ptrB & 0xFFFF);
  if ((long)(a + off + 8) > gRomLen || (long)(b + base + 8) > gRomLen) return 0;
  for (int i = 0; i < 8; i++) {
    if (poses) poses[i] = CtRomByte(gRom, 0x400000L, (long)(a + off + i));
    // Dwells (C1/33F1-3405): ptrB is indexed by the class base $86 only (no facing term), and the raw byte
    // passes through the CC/FBCE remap (battle_facing_engine.md).
    if (dwells) dwells[i] = CtRomByte(gRom, 0x400000L, (long)(ROM_DWELL_REMAP_TBL + CtRomByte(gRom, 0x400000L, (long)(b + base + i))));
  }
  return 1;
}

// CT text encoding (battle_boot.md sec. 4): 'A'-'Z'=0xA0-0xB9, 'a'-'z'=0xBA-0xD3, '0'-'9'=0xD4-0xDD.
static char ctChar(uint8_t c) {
  if (c >= 0xA0 && c <= 0xB9) return (char)('A' + c - 0xA0);
  if (c >= 0xBA && c <= 0xD3) return (char)('a' + c - 0xBA);
  if (c >= 0xD4 && c <= 0xDD) return (char)('0' + c - 0xD4);
  if (c == 0xFF) return ' ';
  return '?';
}
int CtBattleEnemyName(int id, char* out, int cap) {
  if (!out || cap < 1) return 0;
  out[0] = 0;
  if (!gRom || id < 0 || id > 255) return 0;
  const uint8_t* r = CtRomPtr(gRom, gRomLen, ROM_ENEMY_NAMES + (long)id * 11, 11);
  int n = 0;
  // 0xEF is a space, not a terminator: the 11 bytes are the name left-justified and 0xEF-padded, and a
  // two-word name carries 0xEF inside it ("Blue Imp", id 0x0C). Only the trailing run is trimmed.
  for (int i = 0; i < 11 && n < cap - 1; i++) out[n++] = (r[i] == 0xEF) ? ' ' : ctChar(r[i]);
  while (n > 0 && out[n - 1] == ' ') n--;
  out[n] = 0;
  return n;
}

// ------------------------------------------------------------------- Staging
// PC battle-block destinations, ROM ptr table FD/A80B (seats 0-2 = PCs; 0x5FAD+ = the enemy slots).
static const uint16_t kPcBlock[3] = { 0x5E2D, 0x5EAD, 0x5F2D };
#define ENEMY_BLOCK(slot) (0x5FADu + (unsigned)(slot) * 0x80u)

// FD/B033: an item id -> the byte offset of its stat record inside bank $CC. Returns -1 for an id
// with no record (FD/B0B5 `CMP #F2 / BCS ->B0D4` returns with X untouched).
static int battleItemRecOff(int id) {
  if (id < 0x5A) return (int)ROM_EQ_WEAPON + id * 5;
  if (id < 0x7B) return (int)ROM_EQ_ARMOR  + (id - 0x5A) * 3;
  if (id < 0x94) return (int)ROM_EQ_HELMET + (id - 0x7B) * 3;
  if (id < 0xBC) return (int)ROM_EQ_ACCESS + (id - 0x94) * 4;
  if (id < 0xF2) return (int)(ROM_ITEM_AMOUNT_TBL - 0x0C0000u) + (id - 0xBC) * 4;
  return -1;
}
// One C1/CF15 pass (a 3-seat loop over FD/A80B; the caller passes source offset $06, destination $08 and
// count $0A): block[dst .. dst+n-1] = $CC:0000[FD_B033(block[src]) .. +n-1] (1CF2D-1CF35).
static void battleEquipCopy(uint8_t* s, const uint8_t* rom, long romLen,
                            unsigned blk, int srcOff, int dstOff, int n) {
  if (!s || !rom) return;
  int off = battleItemRecOff(s[blk + srcOff]);
  if (off < 0) return;
  for (int i = 0; i < n; i++) {
    long a = 0x0C0000L + off + i;
    if (a >= romLen) break;
    s[blk + dstOff + i] = CtRomByte(rom, 0x400000L, (long)(a));
  }
}
// The PC attack record, resolved per character id (battle_pc_damage_formulas.md sec. 1):
//   C1/BFF3  LDA $B18B / TAX / LDA $AEFF,X        ; seat -> charId (0xFF = empty seat)
//   C1/BFFF  LDA $CC2583,X / STA $B18C            ; charId -> the action id 0x75..0x7B
//   C1/D53A  $B2C3 = $B18C * 11                   ; the 11-byte action record
//   C1/D5CD  LDA $CC1BF0,X / STA $B2C8            ; = CC/1BEB[$B2C3 + 5 + $B2C7], bit 7 terminates
//   C1/D5EF  LDA $CC213F,X / STA $AEE6,Y          ; the 12-byte attack record -> $AEE6..$AEF1
// Record +5 = $16 = the formula type, +9 = $AEEF = the power. There is no weapon-class branch on the
// equipped item: the ranged/melee split is this chain alone. `type` and `pow` are always written; returns
// the record index (for tracing).
static int battlePcAtkRecord(const uint8_t* s, const uint8_t* rom, int atkCmb, int* type, int* pow) {
  int rec = 0x3A;                                            // the ROM's own value for 4 of 7 charIds
  int cid = (s && atkCmb >= 0 && atkCmb < 3) ? s[0xAEFF + atkCmb] : 0xFF;
  if (rom && cid < 8) {
    int act = CtRomByte(rom, 0x400000L, (long)(ROM_PC_ACTION_SEL + cid));                  // C1/BFFF
    int r   = CtRomByte(rom, 0x400000L, (long)(ROM_PC_ACT_REC + act * 11 + 5));            // C1/D5CD ($B2C7 = 0: the first entry)
    if (!(r & 0x80)) rec = r;                                // C1/D5D4 BIT #80 = list terminator
  }
  if (type) *type = rom ? CtRomByte(rom, 0x400000L, (long)(ROM_PC_ATK_REC + rec * 12 + 5)) : 1;
  if (pow)  *pow  = rom ? CtRomByte(rom, 0x400000L, (long)(ROM_PC_ATK_REC + rec * 12 + 9)) : 8;
  return rec;
}

// C1/FC00-FC7B -- the battle-boot equipment derive for one PC block (battle_pc_damage_formulas.md sec. 3).
// The block is a copy of the field sheet, whose +0x41..+0x4F ship as FF placeholders; the boot overwrites
// them from the equipped items' records:
//   1FC08 $06=$29 $08=$43 $0A=06 / JSR C1/CF15     weapon    -> block+0x43..+0x48
//   1FC17 $06=$27 $08=$70 $0A=03 / JSR C1/CF15     helmet    -> block+0x70..+0x72
//   1FC26 $06=$28 $08=$48 $0A=03 / JSR C1/CF15     armor     -> block+0x48..+0x4A  (over the
//   1FC35 $06=$2A $08=$4B $0A=04 / JSR C1/CF15     accessory -> block+0x4B..+0x4E   weapon's 6th)
//   1FC5D +0x3E = min(0xFF, +0x37 + +0x48 + +0x70)  = stamina + armor def + helmet def
// FD/B141 / FD/B14D -- apply one stat-bonus pair. B141 reads the index from the 6-byte equipment record
// (`LDA $CC0004,X / BNE`, zero = nothing); B14D is entered with it in A (the accessory pass). `ASL / ADC $0E`
// (= $29D7) indexes [flags, amount] pairs in bank CC; the flags are walked MSB first, each set bit adding
// the amount to one stat with its own ceiling:
//   bit7 +36 (<63)  bit6 +38 (<10)  bit5 +37 (<63)  bit4 +3A (<63)  bit3 +3B (carry -> FF)  bit2 +39 (<63)
//   bit1 +3C (<63)          -- `CMP #63 / BCC / LDA #63` tests the 8-bit sum, so a wrapped sum is kept.
static void battleStatBonusPair(uint8_t* s, const uint8_t* rom, long romLen, unsigned blk, int idx) {
  long x = 0x0C0000L + 0x29D7L + (long)idx * 2;                  // B14D-B157: A*2 + $0E
  if (x + 1 >= romLen) return;
  int amt = CtRomByte(rom, 0x400000L, (long)(x + 1)), f = CtRomByte(rom, 0x400000L, (long)(x));                              // B159 $0A / B15F $04
  static const struct { int off, cap; } st[7] = { {0x36,0x63}, {0x38,0x10}, {0x37,0x63}, {0x3A,0x63},
                                                  {0x3B,-1}, {0x39,0x63}, {0x3C,0x63} };
  for (int k = 0; k < 7; k++, f = (f << 1) & 0xFF) {             // BPL / ASL $04, seven times
    if (!(f & 0x80)) continue;
    int v = s[blk + st[k].off] + amt;
    if (st[k].cap < 0) v = (v > 0xFF) ? 0xFF : v;                // B1CB BCC / LDA #FF
    else { v &= 0xFF; if (v >= st[k].cap) v = st[k].cap; }       // CMP #cap / BCC / LDA #cap
    s[blk + st[k].off] = (uint8_t)v;
  }
}
// C1/CF69 -- the record's +5 byte: low nibble = amount, high four bits = which of +3F/+40/+41/+42 get it
// (MSB first, plain 8-bit adds, no ceiling).
static void battleStatBonusRes(uint8_t* s, const uint8_t* rom, long romLen, unsigned blk, long rec) {
  if (rec + 5 >= romLen) return;
  int f = CtRomByte(rom, 0x400000L, (long)(rec + 5));                                          // CF6C LDA $CC0005,X / BNE
  if (!f) return;
  int amt = f & 0x0F;
  for (int k = 0; k < 4; k++, f = (f << 1) & 0xFF)
    if (f & 0x80) s[blk + 0x3F + k] = (uint8_t)(s[blk + 0x3F + k] + amt);
}
static void battlePcEquipDerive(uint8_t* s, const uint8_t* rom, long romLen, unsigned blk) {
  if (!s || !rom) return;
  // C1/CE3A (for the three seats at C1/FBF3-FBFD, before the C1/FC00 copies below): the sheet's base stats
  // +0B..+11 become the battle stats +36..+3C, then the weapon ($29), armor ($28-$5A) and helmet ($27-$7B)
  // each add their 6-byte record's bonuses (CC/06A4, CC/08C0, CC/0986 + id*6): FD/B141 for +36..+3C and
  // C1/CF69 for +3F..+42. This matters where the sheets come straight from CC:0000 (FD/B2DE, the demo
  // battle), whose +36.. are FF placeholders.
  s[blk + 0x36] = s[blk + 0x0B]; s[blk + 0x38] = s[blk + 0x0D]; s[blk + 0x37] = s[blk + 0x0C];   // CE59-CE68
  s[blk + 0x3A] = s[blk + 0x0F]; s[blk + 0x3B] = s[blk + 0x10];                                   // CE6B-CE74
  s[blk + 0x39] = s[blk + 0x0E]; s[blk + 0x3C] = s[blk + 0x11];                                   // CE77-CE80
  static const struct { int field, sub, base; } eq[3] = { {0x29, 0x00, 0x06A4}, {0x28, 0x5A, 0x08C0},
                                                          {0x27, 0x7B, 0x0986} };
  for (int k = 0; k < 3; k++) {                                  // CE83 / CEB0 / CEE2
    int id = (s[blk + eq[k].field] - eq[k].sub) & 0xFF;          // `SEC / SBC #sub` in 8 bits (TDC above)
    long rec = 0x0C0000L + eq[k].base + (long)id * 6;            // C1/C90B: id * 6, `ADC #base`
    if (rec + 5 >= romLen) continue;
    if (CtRomByte(rom, 0x400000L, (long)(rec + 4))) battleStatBonusPair(s, rom, romLen, blk, CtRomByte(rom, 0x400000L, (long)(rec + 4)));   // JSL FD/B141 ($0E = $29D7)
    battleStatBonusRes(s, rom, romLen, blk, rec);                                // JSR C1/CF69
  }
  battleEquipCopy(s, rom, romLen, blk, 0x29, 0x43, 6);         // 1FC08: weapon
  battleEquipCopy(s, rom, romLen, blk, 0x27, 0x70, 3);         // 1FC17: helmet
  battleEquipCopy(s, rom, romLen, blk, 0x28, 0x48, 3);         // 1FC26: armor
  battleEquipCopy(s, rom, romLen, blk, 0x2A, 0x4B, 4);         // 1FC35: accessory
  int def = (int)s[blk + 0x37] + (int)s[blk + 0x48] + (int)s[blk + 0x70];   // 1FC5D-1FC7B
  s[blk + 0x3E] = (uint8_t)(def > 0xFF ? 0xFF : def);          // 1FC71 CMP #00FF / BCC
  // 1FC7F: the accessory's stat pair -- `LDA $004C,Y / BIT #40 / BEQ / LDA $004D,Y / BEQ`, then JSL FD/B14D
  // with that byte in A ($0E = $29D7): the same walk as the equipment's.
  if ((s[blk + 0x4C] & 0x40) && s[blk + 0x4D]) battleStatBonusPair(s, rom, romLen, blk, s[blk + 0x4D]);
  // 1FC98-1FCEC: +3D, the attack. `LDA $AEFF,Y / CMP #01|#02` picks +3A (Marle, Lucca) else +36 as the stat.
  // Note: the other term is `LDA $CC0000,X` read after 1FCC8/1FCD1 `LDX $12` reloaded X with the block
  // address, so it is the ROM byte at CC:[block]; the weapon-record index 1FCB1 put in X is discarded. The
  // 16-bit `ADC / BCC` cannot carry for two bytes, so the low byte is stored.
  { int cid = s[blk + 0x00];                                     // (the seat's charId: block +0 is the sheet's)
    int stat = (cid == 1 || cid == 2) ? s[blk + 0x3A] : s[blk + 0x36];
    long rb = 0x0C0000L + (long)blk;
    if (rb < romLen) s[blk + 0x3D] = (uint8_t)(stat + CtRomByte(rom, 0x400000L, (long)(rb))); }
}

// ---- Sound wire (battle_sfx_ops.md sec. 4). Module-scoped like ct_vm.c's VM sink: battle.c stages the
// $1E00 mailbox and the host performs the `JSL $C7:0004`. ----
#define CT_BATTLE_NL "\n"   /* one place for the trace newline */
static CtBattleSoundSink gBattleSnd;
static int gBattleSndOn = 0;
void CtBattleSetSoundSink(const CtBattleSoundSink* sink) {
  if (sink && sink->post) { gBattleSnd = *sink; gBattleSndOn = 1; }
  else { gBattleSndOn = 0; }
}
// This frame's NMI as the main thread finds it (the post position for CtBattleSoundSink.postRule): the line
// the service's last raster wait releases (CD/09AA's `LDA #40 / JSR CD/3B82` in an action frame, or the
// background program's op C1, CD/1D93; max(b, L + 1) as in battleLineCut), and whether the service ran the
// pad latch (D1/E7DA `JSL CD/0C95` with `$7E` = 1/2 -> CD/091A / CD/09C6 `JSL C2/8002`; `$7E` = 0 in the
// boot is CD/09F1, no latch).
static int gBattleNmiLine = 0, gBattleNmiPad = 0;
static void battleNmiWaitLine(int b) { gBattleNmiLine = b > gBattleNmiLine + 1 ? b : gBattleNmiLine + 1; }
static void battleSndPostJsl(CtBattleHost* h, uint8_t* s) {
  if (!gBattleSnd.postRule) { gBattleSnd.post(gBattleSnd.ctx, s); return; }
  // Under the timing rule (docs/DECISIONS.md) the JSL costs its own SPC time from where this frame's NMI left
  // the beam; the frames it crosses stall the main thread (battleTickBody's sndStall gate). An SFX post
  // normally crosses none: the driver answers within one of its loops.
  int n = gBattleSnd.postRule(gBattleSnd.ctx, s, gBattleNmiLine, gBattleNmiPad);
  if (n > 0) {
    h->sndStall += n;
    if (getenv("CT_SNDTRACE"))
      fprintf(stderr, "[snd] battle f%d cmd=%02X p1=%02X: the JSL crossed %d vblank(s) -- the main thread stalls\n",
              h->frames, s[0x1E00], s[0x1E01], n);
  }
}
// One panned SFX post, in the ROM's order (C1/619F-61B5): $1E01 (id), the command $1E00, $1E02 (pan), then
// `JSL C7/0004`. $1E03 is left alone: no handler in the family writes it.
static int battleSfxPost(CtBattleHost* h, uint8_t cmd, uint8_t id, uint8_t pan) {
  if (!gBattleSndOn) return 0;                    // no host wire -> stage nothing (byte-identical headless)
  uint8_t* s = h->mem;
  s[0x1E01] = id; s[0x1E00] = cmd; s[0x1E02] = pan;
  int v0 = (gBattleSnd.voices) ? gBattleSnd.voices(gBattleSnd.ctx) : -1;
  battleSndPostJsl(h, s);
  // Did a sound come out? (the staging is traced elsewhere)
  if (getenv("CT_BATTLE_SFXVOICES")) {
    int v1 = (gBattleSnd.voices) ? gBattleSnd.voices(gBattleSnd.ctx) : -1;
    fprintf(stderr, "battlesfxout f%d cmd=%02X id=%02X pan=%02X voices %d -> %d\n",
            h->frames, cmd, id, pan, v0, v1);
  }
  return 1;
}
// The same post without a pan write. C1/40D3-40DD is `LDA #FF / STA $1E01 / LDA #18 / STA $1E00 /
// JSL $C7:0004` with no $1E02 store, so the driver sees whatever pan the previous post left.
static int battleSfxPostNoPan(CtBattleHost* h, uint8_t cmd, uint8_t id) {
  if (!gBattleSndOn) return 0;
  uint8_t* s = h->mem;
  s[0x1E01] = id; s[0x1E00] = cmd;
  battleSndPostJsl(h, s);
  return 1;
}
// ---- Battle UI blip (battle_ui_sfx_sites.md). `C1/1B55: STZ $1E01 / LDA #19 / STA $1E00 / LDA #80 /
// STA $1E02 / JSL C7/0004` -- id 00, cmd $19, pan $80. It is the whole cursor/confirm/cancel sound of the
// battle menu (29 `JSR $1B55` sites, no other caller); bank C1 has no separate confirm, cancel or buzz id.
static void battleUiBlip(CtBattleHost* h, const char* romSite, const char* pass) {
  if (battleSfxPost(h, 0x19, 0x00, 0x80) || !gBattleSndOn)
    if (getenv("CT_BATTLE_TRACE"))
      // `pass=` names the menu pass that posted it: `live` = the idle loop's C1/10C6, `frozen` = an action
      // loop's C1/10FA (battleMenuPass). $A013 alone cannot tell them apart.
      fprintf(stderr, "battlesfx f%d cursor-blip id=00 pan=80 (C1/%s) pass=%s A013=%d\n",
              h->frames, romSite, pass, h->mem[0xA013]);
}
// The blip dispatch, C1/115F. Each of the 29 sites is a `JSR C1/1B55` right before the dispatcher's
// `JMP <handler>`, so the ROM blips on the button edge and the handler's own veto comes afterwards.
// Dispatch order, as C1/115F:
//   `LDA $9609 / BEQ / JMP C1/1561`   target-select first (even with a submenu open)
//   `LDA $95DB / BEQ / DEC A / BNE / JMP C1/1320` tech, `JMP C1/143D` item, else the command level C1/118F
// Called from battleMenuInput, the handler both passes (C1/10C6 and C1/10FA) run.
static void battleUiBlipDispatch(CtBattleHost* h, int aE, int bE, int upE, int dnE, int lE, int rE,
                                 const char* pass) {
  uint8_t* s = h->mem;
  const char* site = 0;
  if (s[0x9609] != 0) {                              // --- target-select (C1/1561), dispatched first
    if      (aE)        site = "15EE";               //   A/X confirm   ($EE & C0)
    else if (bE)        site = "1574";               //   B cancel      ($EE & 08)
    else if (dnE || rE) site = "1602";               //   Right/Down -> next ($EF & 05)
    else if (upE || lE) site = "1611";               //   Left/Up    -> prev ($EF & 0A)
  } else if (h->techOpen) {                          // --- tech list (C1/1320)
    if      (aE)        site = "1334";               //   A confirm
    else if (bE)        site = "1340";               //   B cancel
    else if (upE || lE) site = "1350";               //   Up/Left  -> prev
    else if (dnE || rE) site = "1360";               //   Down/Right -> next
  } else if (h->itemOpen) {                          // --- item list (C1/143D)
    if      (aE)        site = "1443";
    else if (bE)        site = "144F";
    else if (upE)       site = "145F";               //   (Up and Left come in as up, Down and Right as down)
    else if (dnE)       site = "146F";
    else if (lE)        site = "147B";               //   L -> C1/151C
    else if (rE)        site = "1487";               //   R -> C1/1537
  } else {                                           // --- command level (C1/118F)
    if      (aE)        site = "11D8";               //   A -> C1/127B (the $A0A7 Tech/Item veto comes after)
    else if (upE)       site = "11B7";               //   Up   -> C1/1250
    else if (dnE)       site = "11C3";               //   Down -> C1/1264
    // The ready-PC switch is silent with a single enqueued PC: C1/11E1 / C1/1218 `LDA $A6DE / DEC A /
    // BEQ ->skip` skip only the JSR; the $A6DD head still cycles.
    else if (lE || rE) {
      site = (s[0xA6DE] > 1) ? (lE ? "11E7" : "121E") : 0;
      // The gate's decision is traced, so a check can see the silent case (regress.py matches substrings).
      if (getenv("CT_BATTLE_TRACE"))
        fprintf(stderr, "battlesfx f%d ready-switch A6DE=%d blip=%d pass=%s (C1/11E1)\n",
                h->frames, s[0xA6DE], site ? 1 : 0, pass);
    }
  }
  if (site) battleUiBlip(h, site, pass);
}
// ---- The strip's enemy-name list (CC/ECB2-CED86) ----
// The HUD's enemy-name field is built once, at battle staging, and never rewritten, so the names stay up
// after the enemies die (through the results screen). CC/ECB2 walks the 8 staged slots -- gates
// `LDA $96F8,X / BEQ` (the per-slot present flag, set at CC/EC23) and `LDA $9FFA,X / BMI` (= $9FF7[3+slot],
// the hidden flag from staged record +7 bit 7, CC/EAB5) -- dedupes the ids into the 3-entry list $98FF
// (2-byte stride, high byte 0xFF = unused), counts each type into $98CC[k], and copies each used entry's
// 11-byte name record $CC:6500 + id*11 into the strip's text buffer $7EACBC + k*24 (11 codes + 0xFF, then a
// 12-byte all-0xFF blank row).
static void battleStageEnemyNames(CtBattleHost* h) {
  uint8_t* s = h->mem;
  int ids[3] = { -1, -1, -1 }, cnt[3] = { 0, 0, 0 };
  for (int slot = 0; slot < 8; slot++) {
    const uint8_t* rec = s + 0x29BF + slot * 12;
    if (rec[6] & 0x80) continue;                       // CC/ECC0 `LDA $96F8,X / BEQ`  -- slot empty
    if (rec[7] & 0x80) continue;                       // CC/ECC5 `LDA $9FFA,X / BMI`  -- slot hidden
    int id = rec[5], k = 0;
    while (k < 3 && ids[k] >= 0 && ids[k] != id) k++;  // CC/ECCE-ECDB: already in the list?
    if (k >= 3) continue;                              // (a 4th distinct type: the ROM runs its cursor off
    if (ids[k] < 0) ids[k] = id;                       //  the end of the 3-entry list -- see the dossier)
    cnt[k]++;                                          // CC/ECE6 `INC $80,X`
  }
  for (int k = 0; k < 3; k++) {
    s[0x98FF + k * 2] = (uint8_t)(ids[k] < 0 ? 0xFF : ids[k]);      // the distinct-id list  (CC/ECDF)
    s[0x9900 + k * 2] = (uint8_t)(ids[k] < 0 ? 0xFF : 0x00);        //   high byte 0xFF = unused (CC/ED09)
    s[0x98CC + k] = (uint8_t)cnt[k];                                // per-type count (CC/ECF4-ED00)
    if (ids[k] < 0) continue;                                       // CC/ED0C BMI: no row written
    uint8_t* dst = s + 0xACBC + k * 24;                             // CC/ED53: dest = $ACBC + $80*12,
    memset(dst, 0xFF, 24);                                          //   $80 = k*2 -> 24-byte stride
    if (gRom && gRomLen >= (long)(ROM_ENEMY_NAMES + 256 * 11))
      CtRomCopy(dst, gRom, gRomLen, ROM_ENEMY_NAMES + (long)ids[k] * 11, 11);   // CC/ED20-ED47 + the ED60 copy
  }
  // CT_BATTLE_STAGEDBG: the built list, one line per row.
  if (getenv("CT_BATTLE_STAGEDBG")) {
    for (int k = 0; k < 3; k++) {
      if (ids[k] < 0) continue;
      char nm[16] = ""; CtBattleEnemyName(ids[k], nm, sizeof nm);
      fprintf(stderr, "enemynames: row%d id=%02X x%d '%s'\n", k, ids[k], cnt[k], nm);
    }
  }
}
static void stageAll(CtBattleHost* h) {
  uint8_t* s = h->mem;
  // (0) FD/B2DE, the demo battle's character sheets -- the first call of the boot's staging (C1/FA8F
  // `JSL FDB2DE`, then C1/FA93 `JSL FDB22E` = (i)/(ii) below). `LDA $2989 / BIT #20 / BNE`: a battle whose
  // flags byte has bit 5 (the attract's) does not fight with the party's own sheets:
  //   FD/B33F  STZ $AF1D / LDA #03 / STA $AEC5 / copy CC:0000..022F -> $2600..$282F (the eight base sheets)
  //            / $2400,X := X for X in 0..01FF (8-bit A: 00..FF twice)
  //   FD/B2EC  X = FD:[B99C + $29AC*2]; for each of the 8 sheets (Y += $50): $260B,Y = $260E,Y = $23,
  //            $260C,Y = $80, and four 16-bit words from FD:X -> $2603/$2605/$2607/$2609,Y (HP cur/max, MP cur/max)
  // No writer of $29AC is known (read only, at C1/B743 and FD/B2EC); it reads 00 in the attract.
  if (s[0x2989] & 0x20 && gRom && gRomLen >= 0x3DBA4AL) {
    s[0xAF1D] = 0; s[0xAEC5] = 3;                                         // FD/B33F-B344
    CtRomCopy(s + 0x2600, gRom, gRomLen, 0x0C0000, 0x230);                           // FD/B347-B354
    for (int x = 0; x < 0x200; x++) s[0x2400 + x] = (uint8_t)x;           // FD/B356-B360
    int ti = s[0x29AC] * 2;                                               // FD/B2EC-B2F3
    long src = 0x3D0000L | (CtRomByte(gRom, 0x400000L, (long)(0x3DB99C + ti)) | (CtRomByte(gRom, 0x400000L, (long)(0x3DB99C + ti + 1)) << 8));
    for (int y = 0; y < 0x280 && src + 8 <= gRomLen; y += 0x50, src += 8) {
      s[0x260B + y] = 0x23; s[0x260E + y] = 0x23; s[0x260C + y] = 0x80;   // FD/B2FD-B307
      CtRomCopy(s + 0x2603 + y, gRom, gRomLen, src, 8);                              // FD/B30C-B32B (four LE words)
    }
  }
  // (0b) The command-block / confirm-FIFO state a battle starts from. CF/FB94 zero-fills the battle page
  // ($2D00..$ACEB), FD/A989 a second span, then FD/B7E1-B7E7 `STA $93F3 / $93FA / $9401` (A = FF: each
  // seat's command record +5) and CC/E30F-E318 `STA $99D4..$99D7` (A = FF: the confirm FIFO empty).
  // Note: only these bytes are written here; the engine keeps state of its own in the page CF/FB94 clears.
  memset(s + 0x93EE, 0, 21);                                               // CF/FB94 (this span)
  s[0x93F3] = s[0x93FA] = s[0x9401] = 0xFF;                                // FD/B7E1-B7E7
  // FD/B758-B767 (A = X = 0, FD/B732's `TDC / TAX`): the TP pool $B2DB-$B2DD that FD/ABF6 sums each kill into, $B2AF,
  // and $B2B0..$B2B5 -- the per-seat result flags (bit 7 a level-up, 08 / 04 / 02 a single / dual / triple tech,
  // C1/F205) the results sequencer FD/AD8C reads.
  s[0xB2DB] = s[0xB2DC] = s[0xB2DD] = 0; s[0xB2AF] = 0;
  for (int k = 0; k < 6; k++) s[0xB2B0 + k] = 0;
  s[0x99D4] = s[0x99D5] = s[0x99D6] = s[0x99D7] = 0xFF; s[0x99D8] = 0;     // CC/E30F-E318 / CF/FB94
  // CC/E321, the same run of `STA` with A = FF: the bracket pulse's counter $A4EF, so the frame service's
  // first INC (CF/E5AA, on the band's arm frame) reads 00.
  s[0xA4EF] = 0xFF;
  // FD/A982: `TDC / LDX #AD89 / STA $0000,X / INX / CPX #B3F5 / BCC` -- the whole AI / command page,
  // $AD89..$B3F4, zeroed at staging. Note: stale bytes here matter, e.g. $AF15 bit 6 marks a slot hidden to
  // the alive test (C1/8158).
  memset(s + 0xAD89, 0, 0xB3F5 - 0xAD89);                                  // FD/A982-A98F
  // The span includes $AE91..$AE9B, the action-command bytes CC/F156 turns into the script's roles. An
  // item's roles 1/2 read this clear: no item path writes $AE97/$AE98 (the writers are C1/8D1F, C1/BFC8,
  // C1/9A77/A086/A2CE and C1/C76F/D6C3), so they stay 00.
  // The two bytes CF/EA8A ORs into the ground shadow's OAM attribute: CF/FBAE `LDA $2989 / AND #10 / ORA #20
  // / STA $A5E3` (the OBJ priority) and CC/E37D `LDA #02 / STA $9F46` (palette 1). Not ported: CD/1B90's
  // `EOR #08` that flips it to palette 5 inside an effect program.
  s[0xA5E3] = (uint8_t)((s[0x2989] & 0x10) | 0x20);                        // CF/FBAE-FBB5
  for (int k = 0; k < 11; k++) s[0x99B5 + k] = s[0x9F3B + k] = s[0xA5E3];  // CC/E3F9-E406: the OAM priorities' defaults
  for (int k = 0; k < 8; k++) s[0xAB5F + k] = s[0xAB57 + k] = s[0xA5E3];   // CC/E408-E412 (the effect objects')
  s[0x9F46] = 0x02;                                                        // CC/E37D-E37F
  // (i) party seats: $AEFF+seat <- $2980 (FD/B26C-B277). Bit 7 set = empty slot -> 0xFF.
  int pcs = 0;
  for (int k = 0; k < 3; k++) {
    uint8_t id = s[0x2980 + k];
    s[0xAEFF + k] = (id & 0x80) ? 0xFF : id;
    // ...and the staged roster $AF0A,Y, the gate C1/B279 reads before touching a combatant
    // (`LDA $AF0A,Y / CMP #FF`); C1/B28B/B28E copies it into $AEFF, so at staging the two are the same byte.
    s[0xAF0A + k] = s[0xAEFF + k];
    if (!(id & 0x80)) pcs++;
  }
  s[0xAEC5] = (uint8_t)pcs;                          // PC count (FD/B27x; battle-side actor loop bound)
  s[0x0024] = 0;                                     // FD/B280 STZ $24 (the all-fallen flag C1/8133 tests)
  // FD/B280-B2A1: the character -> seat map $B1BE,charId (`LDA #FF` into $B1BE..$B1C4, then for each present
  // seat X `LDA $AEFF,X / TAY / TXA / STA $B1BE,Y`). A tech names its participants by character (CC:249F)
  // and the executor turns them into seats through this map (C1/D605, C1/CC76).
  for (int c = 0; c < 7; c++) s[0xB1BE + c] = 0xFF;
  for (int k = 0; k < 3; k++) if (s[0xAEFF + k] != 0xFF && s[0xAEFF + k] < 7) s[0xB1BE + s[0xAEFF + k]] = (uint8_t)k;
  // (ii) enemy ids from the staged slot records $29BF+12k (FD/B2A9-B2D8: +5 = id, +6 bit 7 = empty,
  // +7 bit 7 = hidden -> not alive and $AF15 |= 0x80).
  for (int slot = 0; slot < 8; slot++) {
    const uint8_t* rec = s + 0x29BF + slot * 12;
    if (rec[6] & 0x80) { s[0xAF02 + slot] = 0xFF; s[0xAF0D + slot] = 0xFF; continue; }
    s[0xAF02 + slot] = rec[5];
    s[0xAF0D + slot] = rec[5];
    if (rec[7] & 0x80) { s[0xAF02 + slot] = 0xFF; s[0xAF15 + slot] |= 0x80; }   // hidden (FD/B2C1-C6)
  }
  // Note: $AEC6 is the slot count, not the enemy count. FD/B2C9 `INC $AEC6` is the branch target of both
  // the empty test (B2AC BMI) and the hidden test (B2BA BPL), so it runs on all 8 passes of the loop.
  s[0xAEC6] = 8;
  // (iii) PC battle blocks: 0x50-byte copy of the char sheet $7E2600 + charid*0x50 (FD/AE7D-AE8B).
  for (int seat = 0; seat < 3; seat++) {
    uint8_t id = s[0xAEFF + seat];
    if (id == 0xFF || id >= 8) continue;
    memcpy(s + kPcBlock[seat], s + 0x2600 + (size_t)id * 0x50, 0x50);
    // FD/B3FE -- the four resistance bytes +3F..+42: `LDA #04` into all four, then the sheet's +01 picks one
    // of them for 05 (`BIT #80/#40/#20/#10` -> +3F/+40/+41/+42; none set -> all stay 04). C1/CF69 later adds
    // the equipment's nibbles on top.
    { unsigned b = kPcBlock[seat]; uint8_t e = s[b + 0x01];
      for (int k = 0; k < 4; k++) s[b + 0x3F + k] = 0x04;                                  // FD/B405-B410
      int k = (e & 0x80) ? 0 : (e & 0x40) ? 1 : (e & 0x20) ? 2 : (e & 0x10) ? 3 : -1;     // FD/B413-B431
      if (k >= 0) s[b + 0x3F + k] = 0x05; }                                                // FD/B432
    battlePcEquipDerive(s, gRom, gRomLen, kPcBlock[seat]);   // C1/FC00-FC7B (every charId, from the ROM)
    if (getenv("CT_BATTLE_TRACE")) {   // the derived block, per boot
      const uint8_t* b = s + kPcBlock[seat];
      fprintf(stderr, "pcblock seat=%d cid=%d eq=%02X/%02X/%02X/%02X +36=%02X +37=%02X +3A=%02X"
                      " +3E=%02X +43=%02X +45=%02X +48=%02X +70=%02X\n",
              seat, id, b[0x27], b[0x28], b[0x29], b[0x2A], b[0x36], b[0x37], b[0x3A],
              b[0x3E], b[0x43], b[0x45], b[0x48], b[0x70]);
    }
  }
  // (iii.a) FD/AE9E-AEC3: each seat's accessory id (block +0x2A) into $B3BA/$B3BB/$B3BC, counting the $A9s
  // into $B3BD. C1/CBF6 reads it to scale a tech's MP cost (A2 halves, A3 quarters).
  s[0xB3BD] = 0;                                     // (inside FD/A982's `STA $0000,X` clear of $AD89..$B3F4)
  for (int seat = 0; seat < 3; seat++) {
    s[0xB3BA + seat] = s[kPcBlock[seat] + 0x2A];
    if (s[0xB3BA + seat] == 0xA9) s[0xB3BD]++;
  }
  // (iii.b) The $1C48 equipped-weapon records (FD/AF04, battle_sfx_ops_inputs.md sec. 1.3): 3 entries of
  // stride 5 over slots 0-2, per-slot base from FD/A80B (= kPcBlock). Byte +0 is `LDA $0029,X`, the block's
  // equipped weapon id; `BEQ` at 3DAF18 leaves the record blank with no weapon; +2/+3 are the constants
  // #80 / #01 (3DAF5F/3DAF64). $A4E7 indexes this. Not derived and not written: +4 (the 3DAF4D LSR loop's
  // output).
  for (int seat = 0; seat < 3; seat++) {
    uint8_t* rec = s + 0x1C48 + (size_t)seat * 5;                // stride 5 (3DAF6C `ADC #0005`)
    uint8_t w = s[kPcBlock[seat] + 0x29];                        // 3DAF13 `LDA $0029,X`
    rec[0] = w;                                                   // 3DAF2E `STA $001C48,X`
    if (w) { rec[2] = 0x80; rec[3] = 0x01; }                     // 3DAF5F / 3DAF64 (skipped by 3DAF18 BEQ)
  }
  // (iv) enemy stat blocks from ROM CC/4700 + id*23 (FD/B438-B4D0, block = $5FAD + slot*0x80), eight of
  // them: FD/B438 derives Y = slot*0x80 with no bound of its own, and C1/8357's sweep runs `CPY #0400` =
  // 8 passes.
  for (int slot = 0; slot < 8; slot++) {
    uint8_t id = s[0xAF0D + slot];
    uint32_t b = ENEMY_BLOCK(slot);
    if (id == 0xFF) {                                // empty slot: id FF, HP 1/1 (battle_boot.md sec. 2)
      s[b + 0] = 0xFF;
      s[b + 3] = 1; s[b + 4] = 0; s[b + 5] = 1; s[b + 6] = 0;
      continue;
    }
    s[b + 0] = id;
    if (gRom && gRomLen >= (long)(ROM_ENEMY_STATS + 256 * 23)) {
      const uint8_t* rec = CtRomPtr(gRom, gRomLen, ROM_ENEMY_STATS + (long)id * 23, 23);
      s[b + 3] = rec[0]; s[b + 4] = rec[1];          // curHP  (FD/B460 writer; GATO $6130 = 0x004C)
      s[b + 5] = rec[0]; s[b + 6] = rec[1];          // maxHP  (FD/B475; the rec HP word duplicated)
      s[b + 0x12] = rec[2];                          // rec+2 -> $5FBF,Y
      memcpy(s + b + 0x22, rec + 3, 5);              // rec+3..7 -> $5FCF+,Y
      // FD/B438's tail is two copies: FD/B4AF-B4BE moves 12 bytes (`CMP #0C`) to block+0x37 and FD/B4C4-B4D3
      // moves 3 more (`CMP #03`) to `$5FC6,Y` = block+0x19 (+0x1B is read by the enemy attack-record law).
      memcpy(s + b + 0x37, rec + 8, 12);             // rec+8..19  -> block+0x37
      memcpy(s + b + 0x19, rec + 20, 3);             // rec+20..22 -> block+0x19 ($5FC6,Y)
    }
  }
  // C1/FAB9 `JSL FDB121`, right after the FD/B438 loop: `LDA $5E47,X / AND #03 / STA $A020,Y` eight times,
  // X += $80 -- block +0x1A & 3 into `$A01D,cmb` for the eight enemy slots. CD/0043's D0087 reads bit 0
  // (the boss death, CD/0E05 #38).
  for (int slot = 0; slot < 8; slot++) s[0xA020 + slot] = (uint8_t)(s[ENEMY_BLOCK(slot) + 0x1A] & 0x03);
  // (v) C1/EA9D zeroes the status region at combat reset (battle_status_pipeline.md sec. 2/9): a battle
  // starts without status. The block sources can carry stale bits in status byte +0x1E, which the C1/8660
  // can't-act skip and the C1/DCAD wake would read as live sleep, so +0x1E is cleared here. EA9D also zeroes
  // +0x1F..+0x26; the port leaves +0x1F to the source (no +0x1F status is modelled, and the heal_cure fixture
  // presets a +0x1F bit the cure keeps) and keeps the immunity +0x22..+0x26 staged in (iv).
  for (int seat = 0; seat < 3; seat++) s[(0x5E2Du + (unsigned)seat * 0x80u) + 0x1E] = 0;
  for (int slot = 0; slot < 8; slot++) s[ENEMY_BLOCK(slot) + 0x1E] = 0;   // all eight blocks (iv)
  // (vi) the strip's enemy-name list, built once here (CC/ECB2, above).
  battleStageEnemyNames(h);
}

// C1/8357: the controller-2 debug instant-end -- zero every enemy curHP ($5FB0,Y), set $5FCA,Y = 0x80
// (Y = slot*0x80), then store outcome 0 (TDC/STA $7F01EC). Eight slots (C1/8372 `CPY #0400`).
static void debugEnd(CtBattleHost* h) {
  uint8_t* s = h->mem;
  for (int slot = 0; slot < 8; slot++) {
    uint32_t b = ENEMY_BLOCK(slot);
    s[b + 3] = 0; s[b + 4] = 0;                      // curHP := 0 ($5FB0,Y)
    s[b + 0x1D] = 0x80;                              // $5FCA,Y := 0x80
  }
  h->glb[0x1EC] = 0;                                 // outcome 0 (victory/normal end)
}

// ============================================================================
// The ATB battle loop (battle_loop.md part 2 and its addenda).
//
// Combatant model (a single 11-slot index space over the two staged block arrays):
//   idx 0..2  = PC seats     block $5E2D + idx*0x80     ; alive iff party $2980+idx      != 0x80
//   idx 3..10 = enemy slots  block $5FAD + (idx-3)*0x80 ; alive iff $AF02+(idx-3)         != 0xFF
// Per-actor countdown timer $AFAB+idx (-1/tick, C1/8267); reload table $B158+idx (C1/BCEB); bar max
// $9F22+idx (the timer's last load value, battle_hud_render.md addendum 2 sec. A). PC ready queue $A6D9+,
// head $A6DD / tail $A6DE. Current actor $95D5 (0xFF = none, C1/1153); command sub-mode gates
// $95DB/$9609 (0/0 = idle, awaiting input); Att/Tech/Item cursor row $95DC.
// ============================================================================
// The pre-combat window (battle_loop.md sec. J): boot + HUD slide, then the `$993A` ramp, a static pause
// before the ATB starts counting; the combatants idle through it. battleBootIntro derives its length.
// During the intro every present timer is held equal to $9F22 at this value, so the bars draw empty
// (fill = 32 - ((timer*256/max) >> 3) is 0 whenever timer == max). The ROM's own sentinel is the 16-bit
// $AFAB = 0x011F, out of the byte timer's range; 0xFF stands in for it. battleCombatStart() overwrites the
// timers before any decrement, so the value never aliases the absent-slot 0xFF in logic.
#define CT_BATTLE_TMR_INTRO 0xFF

// ---- The main loop's iteration: two frames (oracle_logical_frames.md sec. 4) ----
// One iteration of the battle main loop (C1/8120-8345) is the idle tick C1/106E, which waits twice (C1/109D and
// C1/10BD `JSR C1/007E`), then the tail (C1/812C JSL FD/ACFD, C1/8130 the dead-flag sweep, the end tests,
// C1/81CA's Wait gate, the timer pass C1/8231, the cursors C1/82A2, the handlers C1/8313) and the next head
// (C1/8120 INC $0027, C1/106E-109C). Under the timing rule (docs/DECISIONS.md) every iteration is two frames:
//   frame A  the NMI's upload service CF/E3F8 (`LDA $A013 / BNE / LDA $E5 / BEQ` -> CF/E477 INC $A4), then C1/109D's
//            wait returns: C1/10A4-10A9 the walk dispatch on $A4, C1/3714, C1/283D, C1/10BB STZ $E5
//   frame B  C1/10BD's wait returns: C1/10C4 INC $E5, C1/10C6 the $993A consumer, C1/3714, C1/283D, then the tail and
//            the next head, whose C1/109D wait ends the frame
// $E5 (s[0x00E5]) is 1 through wait 1, 0 through wait 2, and 0 from C1/4062 (the action's setup) to the next
// C1/10C4, so the first frame A after an action or the teardown INCs nothing. The head's frame (combat start,
// an action's end) is iterPh 0; the teardown, the death routine and the demo's C1/B967 call hold the clock.
// Menu-nav auto-repeat, in logic ticks (battle_hud addendum 2 sec. B). Not derived for the two-frame
// iteration: the menu's own cadence, C1/10C6's $993A consumer, is not ported.
#define CT_BATTLE_NAV_DELAY  6    // ticks before auto-repeat starts (~15 real frames)
#define CT_BATTLE_NAV_REPEAT 2    // ticks between auto-repeat moves (~5 real frames)

static int battleBlock(int idx) {                                 // combatant idx -> $7E block base
  return idx < 3 ? (int)(0x5E2Du + (unsigned)idx * 0x80u) : (int)ENEMY_BLOCK(idx - 3);
}
static int battleAtan2(int D3, int D4, int D5, int D6);           // fwd (defined with the trig block below)
static int battleTrigMul(int angle, int scale);
static int battleS8(int v);
static int battleIsPc(int idx) { return idx < 3; }
static int battlePresent(const uint8_t* s, int idx) {
  if (idx < 0 || idx >= 11) return 0;
  if (idx < 3) return !(s[0x2980 + idx] & 0x80);                  // party roster slot occupied
  return s[0xAF02 + (idx - 3)] != 0xFF;                           // enemy alive-list (FF = dead/absent)
}
// FD/B807-B850 reload builder: $B158[a] = 105 - 6*speed + CC2E31[(speed-1)+(bs&7)*16], speed clamped to 16.
// speed = block+0x38 (FD/B807 reads $0038,X), not +0x0D, the menu-display speed byte.
static int battleReload(const uint8_t* rom, int speed, int bs) {
  if (speed > 16) speed = 16;  if (speed < 1) speed = 1;
  int t = rom ? CtRomByte(rom, 0x400000L, (long)(ROM_RELOAD_TBL + (speed - 1) + (bs & 7) * 16)) : 0;
  return 105 - 6 * speed + t;
}
// C1/AF22 RNG: a draw from table $FD/BA61 indexed by $26 (inherited from WRAM), $26++ per nonzero-range
// draw (C1/AF42 skips the INC when the range is 0). Not ported: the hit-roll RNG at C1/E9F0 (always hit),
// so $26 advances only on the damage bonus.
// fwd: C1/C92A, the engine's only divide -- C1/AF22's modulo is that routine (see below).
static void battleDiv32(uint8_t* s, int carryIn);
static int battleMul16(uint8_t* s, int c);           // fwd: C1/C90B, the multiply (defined beside the divide)
static void battleStatusTimerStage(uint8_t* s);      // fwd: FD/B0D5 + FD/B4E7 + C1/B093 (the status timers' staging)
