              wr16(s, 0xA920 + x4, 0x7FFF); wr16(s, 0xAA3D + x2, 0x7FFF); wr16(s, 0xA922 + x4, 0);   // C1/7115-711E
              wr16(s, 0xA8D4 + x2, 0); wr16(s, 0xA8FA + x2, 0); wr16(s, 0xA96C + x4, 0); wr16(s, 0xA96E + x4, 0); wr16(s, 0xA9DE + x2, 0);   // C1/7121-712D
              if (tr) fprintf(stderr, "asc f%d rel=%d t%d HOPSLIDE cmb%d tt=%02X from=(%d,%d) to=(%d,%d) mid=(%d,%d) step=%04X/%04X speed=%d AAFC=%d\n",
                              h->frames, rel, t, c, a1, lx, ly, gx & 0xFF, gy & 0xFF, s[0xAAF9], s[0xAAFA], sx, sy, speed, rd16(s, 0xAAFC));
