              s[0xA355 + y] = (uint8_t)db; s[0xA5B5 + y] = (uint8_t)db; s[0xA230 + y] = ctBattleFaceTab[db];   // C1/72B7-72C4
              s[0xA38E + y] = s[0xA2B0]; s[0xA3A1 + y] = s[0xA2B2];        // C1/72C7-72D0
              s[0xA2F6 + y] = 1; s[0xA878 + y] = 0; s[0xA31C + y] = 0; s[0xA1E0 + y] = 0;   // C1/72D3-72DF
              s[0xA368 + y] = s[0xA240 + x2]; s[0xA37B + y] = s[0xA250 + x2];   // C1/72E5-72EE
